import {
  Platform,
  Share,
  StyleSheet,
  TouchableOpacity,
  View,
} from 'react-native';
import ExpandAttachment from '../expand-attachment';
import {useState} from 'react';
import {Icon} from '@ui-kitten/components';

import {useTranslation} from 'react-i18next';
import RNFS, {DownloadFileOptions} from 'react-native-fs';
import Toast from 'react-native-toast-message';
import ReactNativeBlobUtil from 'react-native-blob-util';
import {IReceiptAttach} from '../../../../../../../../../model/interface/receipt.interface';
import {useReceiptServices} from '../../../../../../../../../hooks/apiHooks/useAPI';
import {getConfig} from '../../../../../../../../../services/httpClient';
import TextCM from '../../../../../../../../components/Text';
import {CommonUtils} from '../../../../../../../../../utils';
import {Color, Font} from '../../../../../../../../../constants';
import ModalConfirmCM from '../../../../../../../../components/ModalConfirm';
import {DocumentItem} from '../../../../../../../../../model/interface/qdtha.interface';
type Props = {
  item: DocumentItem;
  getListRelativeFile: () => void;
};

const AttachmentItem = ({item, getListRelativeFile}: Props) => {
  const {t} = useTranslation();
  const ReceiptServices = useReceiptServices();
  const [isExpand, setIsExpand] = useState(false);
  const toggleExpand = () => setIsExpand(!isExpand);
  const [openModalTrash, setOpenModalTrash] = useState(false);
  const [openModalDownload, setOpenModalDownload] = useState(false);
  const handleDeleteAttach = async (item: DocumentItem) => {
    try {
      const res = await ReceiptServices.deleteRelateFileById(
        item.id,
        'accessToken',
      );
      if (res) {
        Toast.show({
          type: 'success',
          text1: t('CM.noti'),
          text2: t('BLDT.delete_attachment_success'),
        });
        getListRelativeFile();
      } else {
        Toast.show({
          type: 'error',
          text1: t('CM.noti'),
          text2: t('BLDT.delete_attachment_fail'),
        });
      }
    } catch (error) {
      console.error(error);
      Toast.show({
        type: 'error',
        text1: t('CM.noti'),
        text2: t('CM.error'),
      });
    } finally {
      setOpenModalTrash(false);
    }
  };

  const handleDownloadAttach = async (
    data: DocumentItem & {keyName?: string; notionId?: string},
    isInfoFile: boolean,
  ) => {
    try {
      let fileName: string = (data as any).fileName;
      if (isInfoFile) {
        fileName = data?.keyName?.replace('/', '_') || '';
      } else {
        fileName = data.fileName;
      }
      if (fileName.includes('/')) {
        fileName = fileName.substring(fileName.lastIndexOf('/') + 1);
      }
      const toFile = `${
        Platform.OS === 'android'
          ? RNFS.DownloadDirectoryPath
          : RNFS.DocumentDirectoryPath
      }/${new Date().getTime()}_${fileName}`;

      if (isInfoFile) {
        await downloadFileInfoForm(
          toFile,
          data.id,
          data?.notionId || '',
          item.ticketId,
        );
      } else {
        if (!data.bucketName) {
          // await downloadFileNotBucketName(toFile, data.name);
        } else {
          await downloadFileWithBucketName(toFile, data.id);
        }
      }
    } catch (error) {
    } finally {
      setOpenModalDownload(false);
    }
  };

  const downloadFileNotBucketName = async (toFile: string, fromUrl: string) => {
    const options: DownloadFileOptions = {
      fromUrl: fromUrl,
      toFile,
      background: true,
      begin: (res: any) => {},
      progress: (res: any) => {
        let percentage = (res.bytesWritten / res.contentLength) * 100;
        // setProgress(percentage);
      },
      connectionTimeout: 1000 * 5,
    };
    try {
      const result = await RNFS.downloadFile(options).promise;
      if (result.statusCode === 200) {
        if (Platform.OS === 'ios') {
          const dataShare = await Share.share({
            url: toFile,
          });
          if (dataShare.action == Share.dismissedAction) {
            Toast.show({
              type: 'error',
              text1: t('CM.noti'),
              text2: t('CM.downloadFail'),
            });
          } else {
            Toast.show({
              type: 'success',
              text1: t('CM.noti'),
              text2: t('CM.downloadSuccess'),
            });
          }
        } else {
          Toast.show({
            type: 'success',
            text1: t('CM.noti'),
            text2: t('CM.downloadSuccess'),
          });
        }
      } else {
        Toast.show({
          type: 'error',
          text1: t('CM.noti'),
          text2: t('CM.downloadFail'),
        });
      }
    } catch (err: any) {
      Toast.show({
        type: 'error',
        text1: t('CM.noti'),
        text2: t('CM.downloadFail'),
      });
    } finally {
      setOpenModalDownload(false);
    }
  };

  const downloadFileWithBucketName = async (toFile: string, id: any) => {
    try {
      Toast.show({
        type: 'info',
        text1: t('CM.noti'),
        text2: t('CM.pleaseWait'),
      });
      const dataBase64 = await ReactNativeBlobUtil.fetch(
        'GET',
        `${
          getConfig().BASE_URL_QDTHA
        }/services/thads-qdtha/api/storage-attaches/download/${id}`,
      )
        .then(res => {
          let status = res.info().status;
          if (status == 200) {
            let base64Str = res.base64();
            return base64Str;
          } else return null;
        })
        .catch(() => null);
      if (dataBase64) {
        try {
          await RNFS.writeFile(toFile, dataBase64, 'base64');
        } catch (error) {
          console.error(error);
        }
        if (Platform.OS === 'ios') {
          const dataShare = await Share.share({
            url: toFile,
          });
          if (dataShare.action == Share.dismissedAction) {
            Toast.show({
              type: 'error',
              text1: t('CM.noti'),
              text2: t('CM.downloadFail'),
            });
          } else {
            Toast.show({
              type: 'success',
              text1: t('CM.noti'),
              text2: t('CM.downloadSuccess'),
            });
          }
        } else {
          Toast.show({
            type: 'success',
            text1: t('CM.noti'),
            text2: t('CM.downloadSuccess'),
          });
        }
      } else {
        Toast.show({
          type: 'error',
          text1: t('CM.noti'),
          text2: t('CM.downloadFail'),
        });
      }
    } catch (error) {
      Toast.show({
        type: 'error',
        text1: t('CM.noti'),
        text2: t('CM.downloadFail'),
      });
    }
  };

  const downloadFileInfoForm = async (
    toFile: string,
    id: any,
    userTaskId: string,
    ticketId: string,
  ) => {
    try {
      const dataBase64 = await ReactNativeBlobUtil.fetch(
        'GET',
        `${
          getConfig().BASE_URL
        }/services/erequest/api/tickets/${ticketId}/userTaskId/${userTaskId}/fileId/${id}/content`,
      )
        .then(res => {
          let status = res.info().status;
          if (status == 200) {
            let base64Str = res.base64();
            return base64Str;
          } else return null;
        })
        .catch(() => null);
      if (dataBase64) {
        await RNFS.writeFile(toFile, dataBase64, 'base64');
        if (Platform.OS === 'ios') {
          const dataShare = await Share.share({
            url: toFile,
          });
          if (dataShare.action == Share.dismissedAction) {
            Toast.show({
              type: 'error',
              text1: t('CM.noti'),
              text2: t('CM.downloadFail'),
            });
          } else {
            Toast.show({
              type: 'success',
              text1: t('CM.noti'),
              text2: t('CM.downloadSuccess'),
            });
          }
        } else {
          Toast.show({
            type: 'success',
            text1: t('CM.noti'),
            text2: t('CM.downloadSuccess'),
          });
        }
      } else {
        Toast.show({
          type: 'error',
          text2: t('CM.downloadFail'),
        });
      }
    } catch (error) {
      Toast.show({
        type: 'error',
        text2: t('CM.downloadFail'),
      });
    }
  };

  return (
    <View key={item.id}>
      <TouchableOpacity
        style={styles.documentItem}
        onPress={() => toggleExpand()}>
        <View style={styles.documentRow}>
          <View style={styles.iconTitleContainer}>
            <View style={styles.iconContainer}>
              <Icon
                name={isExpand ? 'chevron-down' : 'chevron-right'}
                fill={Color.QDTHACMColor}
                width={12}
                height={12}
              />
            </View>
            <TextCM style={styles.documentTitle} numberOfLines={1}>
              {CommonUtils.truncateText(item?.fileName || '', 25)}
            </TextCM>
          </View>
          <TouchableOpacity
            style={styles.trashIcon}
            onPress={() => setOpenModalDownload(true)}>
            <Icon name="download" width={16} height={16} fill={Color.Black} />
          </TouchableOpacity>
        </View>
      </TouchableOpacity>
      {isExpand && <ExpandAttachment item={item} />}

      <ModalConfirmCM
        type="delete"
        title={t('CM.delete_document')}
        content={t('BLDT.delete_document_question')}
        onClose={() => setOpenModalTrash(false)}
        isVisible={openModalTrash}
        labelCancel={t('CM.back')}
        labelConfirm={t('CM.confirm')}
        onConfirm={() => handleDeleteAttach(item)}
      />

      <ModalConfirmCM
        type="info"
        title={t('CM.downloadFile')}
        content={t('BLDT.down_attachment_question')}
        onClose={() => setOpenModalDownload(false)}
        isVisible={openModalDownload}
        labelCancel={t('CM.back')}
        labelConfirm={t('CM.confirm')}
        onConfirm={() => handleDownloadAttach(item, false)}
      />
    </View>
  );
};
export default AttachmentItem;

const styles = StyleSheet.create({
  documentItem: {
    paddingVertical: 12,
  },
  documentRow: {
    flexDirection: 'row',
    alignItems: 'center',
    columnGap: 12,
  },
  iconTitleContainer: {
    flexDirection: 'row',
    alignItems: 'center',
    flex: 1,
    columnGap: 8,
  },
  iconContainer: {
    borderWidth: 1,
    width: 14,
    height: 14,
    borderColor: Color.QDTHACMColor,
    borderRadius: 30,
    justifyContent: 'center',
    alignItems: 'center',
  },
  documentTitle: {
    fontSize: 13,
    fontFamily: Font.InterMedium500,
    color: '#00204DE5',
    flex: 1,
  },
  trashIcon: {
    padding: 4,
  },
});
