import WebView from 'react-native-webview';
import HeaderCM from '../../../../components/Header/HeaderCM';
import {String} from '../../../../../constants';
import {
  useQDTHAService,
  useReceiptServices,
} from '../../../../../hooks/apiHooks/useAPI';
import {useRoute} from '@react-navigation/native';
import {IDocJudgmentDecision} from './interface';
import {useEffect, useState} from 'react';
import Toast from 'react-native-toast-message';
import {useTranslation} from 'react-i18next';
import {ActivityIndicator, View} from 'react-native';

const Van_BanTHA = () => {
  const {t} = useTranslation();
  const QDTHAService = useQDTHAService();
  const ReceiptService = useReceiptServices();
  const route = useRoute<any>();
  const id = route.params?.id || '';
  const [url, setUrl] = useState<string>('');
  const [isLoading, setIsLoading] = useState<boolean>(true);

  useEffect(() => {
    getVanBanTHA();
  }, []);
  const getVanBanTHA = async () => {
    try {
      setIsLoading(true);
      const data = (await QDTHAService.getDocJudgmentDecision(
        id,
      )) as IDocJudgmentDecision[];
      if (data?.length) {
        const formData = new FormData();
        if (!data?.[0]?.bucketName) {
          formData.append('href', data?.[0]?.fileName || '');
        } else {
          formData.append('bucketName', data?.[0]?.bucketName || '');
          formData.append('keyName', data?.[0]?.keyName || '');
          formData.append('beanName', data?.[0]?.beanName || '');
        }

        const response = await ReceiptService.viewFile(formData);
        if (response?.code === 1) {
          setUrl(response?.message);
        } else {
          Toast.show({
            type: 'error',
            text1: t('CM.noti'),
            text2: t('CM.error'),
          });
        }
      } else {
        Toast.show({
          type: 'error',
          text1: t('CM.noti'),
          text2: t('Không có dữ liệu'),
        });
      }
    } catch (error) {
    } finally {
      setIsLoading(false);
    }
  };
  return (
    <>
      <HeaderCM listColor={['#072A7E', '#00CEF3']} title="Văn bản THA" />
      {!isLoading && url ? (
        <WebView
          source={{
            uri: url,
          }}
          style={{flex: 1}}
          javaScriptEnabled={true}
          domStorageEnabled={true}
          startInLoadingState={true}
          scalesPageToFit={true}
          sharedCookiesEnabled={true}
          thirdPartyCookiesEnabled={true}
          injectedJavaScript={String.SCRIPT_SCALE_WEBVIEW}
        />
      ) : (
        <View style={{flex: 1, justifyContent: 'center', alignItems: 'center'}}>
          <ActivityIndicator size={'large'} color={'#055FA4'} />
        </View>
      )}
    </>
  );
};

export default Van_BanTHA;
