import {Icon, IndexPath} from '@ui-kitten/components';
import React, {useState} from 'react';
import {TouchableOpacity, View} from 'react-native';
import DropdownListCM from '../../../../components/DropDownList';
import {useTranslation} from 'react-i18next';
import {Color, Font} from '../../../../../constants';
import TextCM from '../../../../components/Text';
import InputDate from './InputDate';
import {listRequestStatusQDTHA, listSourceOfReceipt} from './helper';

import Toast from 'react-native-toast-message';

import {useConfigStore} from '../../../zustand/config';
import {ValueFilterSearchDYC} from '../..';
type Props = {
  onClose: () => void;
  handleSubmitFilter?: () => void;
  setValueFilterSearch: React.Dispatch<
    React.SetStateAction<ValueFilterSearchDYC | undefined>
  >;
  valueFilterSearch?: ValueFilterSearchDYC;
  type: 'owner' | 'authorized';
};
const ModalFilter = ({
  handleSubmitFilter,
  setValueFilterSearch,
  valueFilterSearch,
  type,
}: Props) => {
  const {t} = useTranslation();
  const {LIST_APPLICATION_STATUS, LIST_ORG} = useConfigStore();
  const [valueFilterSearchState, setValueFilterSearchState] = useState<
    ValueFilterSearchDYC | undefined
  >(valueFilterSearch);

  const onChangeStartDate = (value: string | null) => {
    const newStart = value ? new Date(value) : undefined;
    const {endDate} = valueFilterSearch?.rangeDay ?? {};
    if (endDate && newStart && newStart > endDate) {
      Toast.show({
        type: 'error',
        text1: t('CM.noti'),
        text2: t('BLDT.start_date_not_greater_than_end_date'),
      });
      return;
    }

    setValueFilterSearchState({
      ...valueFilterSearchState,
      rangeDay: {
        ...valueFilterSearchState?.rangeDay,
        startDate: newStart,
      },
    });
  };
  const onChangeEndDate = (value: string | null) => {
    const newEnd = value ? new Date(value) : undefined;
    const {startDate} = valueFilterSearchState?.rangeDay ?? {};
    if (startDate && newEnd && newEnd < startDate) {
      Toast.show({
        type: 'error',
        text1: t('CM.not'),
        text2: t('BLDT.end_date_not_less_than_start_date'),
      });
      return;
    }
    setValueFilterSearchState({
      ...valueFilterSearchState,
      rangeDay: {...valueFilterSearchState?.rangeDay, endDate: newEnd},
    });
  };

  const handleClear = () => {
    setValueFilterSearchState(undefined);
  };

  const handleSubmit = () => {
    setValueFilterSearch(valueFilterSearchState);
    handleSubmitFilter?.();
  };

  return (
    <View style={{backgroundColor: '#fff'}}>
      <View style={{marginVertical: 4}}>
        <TextCM
          style={{
            marginVertical: 8,
            fontFamily: Font.InterMedium500,
            fontSize: 14,
          }}>
          Nguồn nhận
        </TextCM>
        <DropdownListCM
          onSelect={(item: IndexPath[]) => {
            setValueFilterSearchState({...valueFilterSearchState, type: item});
          }}
          valueSelect={valueFilterSearchState?.type}
          placeholder={'Chọn nguồn nhận'}
          multiple={true}
          listData={listSourceOfReceipt}
        />
      </View>

      <View style={{marginVertical: 4, marginBottom: 12}}>
        <TextCM
          style={{
            marginVertical: 8,
            fontFamily: Font.InterMedium500,
            fontSize: 14,
          }}>
          Ngày tiếp nhận
        </TextCM>
        <View
          style={{
            flexDirection: 'row',
            justifyContent: 'space-between',
            alignItems: 'center',
            marginTop: 10,
            columnGap: 8,
          }}>
          <InputDate
            containerStyle={{flex: 1}}
            value={valueFilterSearchState?.rangeDay?.startDate || null}
            onChangeDate={value => {
              onChangeStartDate(value);
            }}
            maxDate={new Date()}
            disabled={false}
          />
          <Icon name="arrow-forward-outline" width={20} height={20} />
          <InputDate
            containerStyle={{flex: 1}}
            value={valueFilterSearchState?.rangeDay?.endDate || null}
            onChangeDate={value => {
              onChangeEndDate(value);
            }}
            maxDate={new Date()}
            disabled={false}
          />
        </View>
      </View>
      <View style={{marginVertical: 4}}>
        <TextCM
          style={{
            marginVertical: 8,
            fontFamily: Font.InterMedium500,
            fontSize: 14,
          }}>
          Trạng thái yêu cầu
        </TextCM>
        <DropdownListCM
          onSelect={(item: IndexPath[]) => {
            setValueFilterSearchState({
              ...valueFilterSearchState,
              requestStatus: item,
            });
          }}
          valueSelect={valueFilterSearchState?.requestStatus}
          placeholder={'Chọn trạng thái yêu cầu'}
          listData={LIST_APPLICATION_STATUS}
          isi18n={true}
          multiple={true}
        />
      </View>
      <View style={{marginVertical: 4, marginBottom: 12}}>
        <TextCM
          style={{
            marginVertical: 8,
            fontFamily: Font.InterMedium500,
            fontSize: 14,
          }}>
          {'Trạng thái quy trình'}
        </TextCM>
        <DropdownListCM
          onSelect={(item: IndexPath[]) => {
            setValueFilterSearchState({
              ...valueFilterSearchState,
              flowStatus: item,
            });
          }}
          valueSelect={valueFilterSearchState?.flowStatus}
          placeholder={'Chọn trạng thái quy trình'}
          multiple={true}
          listData={listRequestStatusQDTHA}
          isi18n={true}
        />
      </View>
      {type === 'authorized' && (
        <View style={{marginVertical: 4}}>
          <TextCM
            style={{
              marginVertical: 8,
              fontFamily: Font.InterMedium500,
              fontSize: 14,
            }}>
            {'Tổ chức'}
          </TextCM>
          <DropdownListCM
            onSelect={(item: IndexPath) => {
              setValueFilterSearchState({
                ...valueFilterSearchState,
                orgIn: item,
              });
            }}
            valueSelect={valueFilterSearchState?.orgIn}
            placeholder={'Chọn tổ chức'}
            listData={LIST_ORG}
            isi18n={true}
          />
        </View>
      )}

      <View
        style={{
          flexDirection: 'row',
          justifyContent: 'space-evenly',
          alignItems: 'center',
          gap: 16,
        }}>
        <TouchableOpacity
          onPress={handleClear}
          style={{
            flex: 1,
            padding: 12,
            backgroundColor: '#E8F5FF',
            borderRadius: 8,
          }}>
          <TextCM style={{color: Color.QDTHACMColor, textAlign: 'center'}}>
            {t('DB.filter.set-default')}
          </TextCM>
        </TouchableOpacity>
        <TouchableOpacity
          onPress={handleSubmit}
          style={{
            flex: 1,
            padding: 12,
            backgroundColor: Color.QDTHACMColor,
            borderRadius: 8,
          }}>
          <TextCM style={{color: '#fff', textAlign: 'center'}}>
            {t('BLDT.filter')}
          </TextCM>
        </TouchableOpacity>
      </View>
    </View>
  );
};

export default ModalFilter;
