import WebView from 'react-native-webview';
import {ActivityIndicator, Platform, View} from 'react-native';
import {useEffect, useState} from 'react';
import Toast from 'react-native-toast-message';
import {t} from 'i18next';
import ReactNativeBlobUtil from 'react-native-blob-util';
import {useRoute} from '@react-navigation/native';
import {useReceiptServices} from '../../../../../../../../../hooks/apiHooks/useAPI';
import {getConfig} from '../../../../../../../../../services/httpClient';
import {CommonUtils} from '../../../../../../../../../utils';
import {IReceiptAttach} from '../../../../../../../../../model/interface/receipt.interface';
import HeaderCM from '../../../../../../../../components/Header/HeaderCM';
import {Color, String} from '../../../../../../../../../constants';
import {SafeAreaView} from 'react-native-safe-area-context';

const ViewDocumentScreen = () => {
  const router = useRoute<any>();
  const item = router.params?.item;
  const ReceiptService = useReceiptServices();
  const [urlWebview, setUrlWebview] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  useEffect(() => {
    handleViewFile(item);
  }, []);
  const getFiles = async (
    userTaskId: string,
    fileId: any,
    fileName: string,
  ) => {
    try {
      const type = fileName?.split('.')?.[1];
      const path = `${ReactNativeBlobUtil.fs.dirs.DocumentDir}/${new Date()
        .getTime()
        .toString()}.${type}`;
      const dataBase64 = await ReactNativeBlobUtil.config({
        path: path,
      })
        .fetch(
          'GET',
          `${getConfig().BASE_URL}/services/erequest/api/tickets/${
            item.ticketId
          }/userTaskId/${userTaskId}/fileId/${fileId}`,
        )
        .then(res => {
          let status = res.info().status;
          if (status == 200) {
            let base64Str = res.path();
            return base64Str;
          } else return null;
        })
        .catch(() => null);
      const file = {
        uri: Platform.OS === 'ios' ? dataBase64 : 'file://' + dataBase64,
        name: `${new Date().getTime().toString()}.${type}`,
        type: CommonUtils.getMimeType(fileName),
      };
      return file;
    } catch (error) {}
  };
  const handleViewFile = async (data: IReceiptAttach & {keyName?: string}) => {
    setIsLoading(true);
    try {
      Toast.show({
        type: 'info',
        text1: t('CM.info'),
        text2: t('TK.viewFile'),
      });
      const formData = new FormData();
      if (data.resource === 'ewriter') {
        const base64String = await getFiles(
          data.userTaskId,
          data?.fileRepositoryId,
          data?.fileName,
        );
        formData.append('file', base64String);
        const dataView = await ReceiptService.viewFile(formData, 'accessToken');
        if (dataView?.code == 1) {
          setUrlWebview(dataView.message);
          setIsLoading(false);
        } else {
          Toast.show({
            type: 'error',
            text1: t('CM.noti'),
            text2: t('CM.error'),
          });
        }
        return;
      }
      let keyName: string = data.keyName || data.name;
      let bucketName: string = data.bucketName;
      let beanName: string = data.beanName;
      if (!bucketName) {
        formData.append('href', data.name);
      } else {
        formData.append('keyName', keyName);
        formData.append('bucketName', bucketName);
        formData.append('beanName', beanName);
      }

      const dataView = await ReceiptService.viewFile(formData, 'accessToken');
      if (dataView?.code == 1) {
        setUrlWebview(dataView.message);
        setIsLoading(false);
      } else {
        Toast.show({
          type: 'error',
          text1: t('CM.info'),
          text2: t('CM.error'),
        });
      }
    } catch (error) {
      Toast.show({
        type: 'error',
        text1: t('CM.info'),
        text2: t('CM.error'),
      });
    }
  };
  return (
    <SafeAreaView style={{flex: 1, backgroundColor: '#fff'}} edges={['bottom']}>
      <HeaderCM
        title={t('CM.attachment')}
        useLinearGradient={false}
        style={{backgroundColor: Color.QDTHACMColor}}
        contentStyle={{backgroundColor: Color.QDTHACMColor}}
      />
      {isLoading ? (
        <View
          style={{
            flex: 1,
            justifyContent: 'center',
            alignItems: 'center',
          }}>
          <ActivityIndicator size="large" color={Color.BgPrimary} />
        </View>
      ) : (
        urlWebview && (
          <WebView
            startInLoadingState
            injectedJavaScript={String.SCRIPT_SCALE_WEBVIEW}
            allowsInlineMediaPlayback={true}
            mediaPlaybackRequiresUserAction={false}
            domStorageEnabled={true}
            javaScriptEnabled={true}
            thirdPartyCookiesEnabled={true}
            sharedCookiesEnabled={true}
            source={{
              uri: urlWebview,
            }}
          />
        )
      )}
    </SafeAreaView>
  );
};
export default ViewDocumentScreen;
